javascript:(function(){ var ENDPOINT_URL = 'https://omoroi-crm.vercel.app/api/ingest/lreach'; var INGEST_TOKEN = 'crm-ingest-secret-2024'; function getRecordsFromNextData() { try { var nd = window.__NEXT_DATA__; if (!nd) return null; return findArraysInObject(nd.props); } catch(e) { return null; } } function findArraysInObject(obj) { if (!obj || typeof obj !== 'object') return null; var keys = ['reservations', 'referrals', 'customers', 'leads', 'records']; for (var i = 0; i < keys.length; i++) { if (Array.isArray(obj[keys[i]]) && obj[keys[i]].length > 0) return obj[keys[i]]; } for (var k in obj) { if (typeof obj[k] === 'object' && !Array.isArray(obj[k])) { var found = findArraysInObject(obj[k]); if (found) return found; } } return null; } function getRecordsFromReact() { try { var root = document.querySelector('#__next'); if (!root) return null; var fiberKey = Object.keys(root).find(function(k){ return k.startsWith('__reactFiber') || k.startsWith('__reactInternalInstance'); }); if (!fiberKey) return null; return searchFiber(root[fiberKey], 0); } catch(e) { return null; } } function searchFiber(fiber, depth) { if (!fiber || depth > 25) return null; try { var state = fiber.memoizedState; while (state) { var ms = state.memoizedState; if (Array.isArray(ms) && ms.length > 3) { var f = ms[0]; if (f && typeof f === 'object' && (f.name || f.id || f.email)) return ms; } state = state.next; } } catch(e) {} return searchFiber(fiber.child, depth+1) || searchFiber(fiber.sibling, depth+1); } function getRecordsFromDOM() { var rows = document.querySelectorAll('table tbody tr'); if (rows.length === 0) return []; var records = []; rows.forEach(function(row) { var cells = row.querySelectorAll('td'); if (cells.length < 2) return; var t = function(i){ return cells[i] ? cells[i].innerText.trim().replace(/\s+/g,' ') : ''; }; var name = t(0); if (!name) return; var memo   = t(6); var parsed = parseMemo(memo); records.push({ name:         name, sendDate:     normDate(t(2)), ca:           t(5) === '-' ? '' : t(5), timing:       parsed.timing, salary:       parsed.salary, hopeSalary:   parsed.hopeSalary, age:          parsed.age, birthDate:    parsed.birthDate, education:    parsed.education, note:         memo, lreachStatus: t(1) }); }); return records; } function normalize(rec) { var memo   = rec.hearingMemo || rec.memo || rec.note || rec.comment || rec['\u30d2\u30a2\u30ea\u30f3\u30b0\u30e1\u30e2'] || ''; var parsed = parseMemo(memo); var phone  = rec.phone || rec.tel || rec.phoneNumber || rec['\u96fb\u8a71\u756a\u53f7'] || parsed.phone || ''; var email  = rec.email || rec.mailAddress || rec.emailAddress || rec['\u30e1\u30fc\u30eb\u30a2\u30c9\u30ec\u30b9'] || parsed.email || ''; return { name:         rec.name       || rec.customerName  || rec.fullName    || '', kana:         rec.kana       || rec.furigana       || parsed.kana    || '', email:        email, phone:        phone, age:          rec.age        || parsed.age         || '', birthDate:    parsed.birthDate || normDate(rec.birthDate || rec.birthday || ''), education:    parsed.education || rec.education || rec.finalEducation || rec['\u6700\u7d42\u5b66\u6b74'] || '', gender:       rec.gender     || parsed.gender      || '', sendDate:     normDate(rec.referralDate || rec.createdAt || rec.scheduledAt || rec.interviewDate || ''), ca:           rec.staffName  || rec.assignee       || rec['\u62c5\u5f53\u8005']      || '', timing:       parsed.timing  || rec.transferTiming || '', salary:       parsed.salary  || String(rec.currentSalary  || ''), hopeSalary:   parsed.hopeSalary || String(rec.desiredSalary || ''), note:         memo, foresmaId:    rec.id         || rec.referralId     || '' }; } function parseMemo(memo) { var r = { salary: '', hopeSalary: '', timing: '', phone: '', email: '', kana: '', age: '', birthDate: '', education: '', gender: '' }; if (!memo) return r; var kanaM = memo.match(/(?:\u3075\u308a\u304c\u306a|\u30d5\u30ea\u30ac\u30ca|\u8aad\u307f)[\s\u3000]*[\uff1a:]\s*([\u3040-\u30ff\u30a0\uff65\s\u3000]+?)(?=\s*\S+[\uff1a:]|\s*$)/); if (kanaM) r.kana = kanaM[1].trim(); var phoneM = memo.match(/\u96fb\u8a71\u756a\u53f7[\s\u3000]*[\uff1a:]\s*(\d[\d\-\s]{8,14})/); if (phoneM) r.phone = phoneM[1].replace(/\s/g,'').trim(); var emailM = memo.match(/(?:\u30e1\u30fc\u30eb\u30a2\u30c9\u30ec\u30b9|Email|email)[\s\u3000]*[\uff1a:]\s*([\w.+\-]+@[\w.\-]+\.[a-zA-Z]{2,})/); if (emailM) r.email = emailM[1].trim(); var genderM = memo.match(/\u6027\u5225[\s\u3000]*[\uff1a:]\s*(\u7537\u6027?|\u5973\u6027?)/); if (genderM) r.gender = genderM[1].trim(); var birthM = memo.match(/\u751f\u5e74\u6708\u65e5[\s\u3000]*[\uff1a:]\s*(\d{4})[\u5e74\/\-](\d{1,2})[\u6708\/\-](\d{1,2})/); if (birthM) { r.birthDate = birthM[1] + '-' + ('0'+birthM[2]).slice(-2) + '-' + ('0'+birthM[3]).slice(-2); var today = new Date(); var age = today.getFullYear() - parseInt(birthM[1]); var md = today.getMonth() + 1 - parseInt(birthM[2]); if (md < 0 || (md === 0 && today.getDate() < parseInt(birthM[3]))) age--; r.age = String(age); } var eduM = memo.match(/(?:\u6700\u7d42\u5b66\u6b74|\u5b66\u6b74)[\s\u3000]*[\uff1a:]\s*([^\n]{1,50})/); if (eduM) r.education = eduM[1].trim(); var s  = memo.match(/\u73fe[\u5728\u8077]?\u5e74\u53ce\s*[\uff1a:]\s*([\d,\uff0c\u4e07\u5186]+)/); var hs = memo.match(/\u5e0c\u671b\u5e74\u53ce\s*[\uff1a:]\s*([\d,\uff0c\u4e07\u5186]+)/); var t  = memo.match(/\u8ee2\u8077\u6642\u671f\s*[\uff1a:]\s*([^\n\u3002\u3001\u3000]{1,30})/); if (s)  r.salary     = s[1].trim(); if (hs) r.hopeSalary = hs[1].trim(); if (t)  r.timing     = t[1].trim(); return r; } function normDate(str) { if (!str) return ''; var m = str.match(/(\d{4})[\/\-\u5e74](\d{1,2})[\/\-\u6708](\d{1,2})/); if (!m) return str; return m[1] + '-' + ('0'+m[2]).slice(-2) + '-' + ('0'+m[3]).slice(-2); } var raw     = getRecordsFromNextData() || getRecordsFromReact(); var records; if (raw && raw.length > 0) { records = raw.map(normalize).filter(function(r){ return r.name; }); } else { records = getRecordsFromDOM().filter(function(r){ return r.name; }); } if (records.length === 0) { alert('\u3010CRM\u53d6\u8fbc\u3011\u30c7\u30fc\u30bf\u304c\u53d6\u5f97\u3067\u304d\u307e\u305b\u3093\u3067\u3057\u305f\u3002\nLreach CRM\u306e\u300c\u9867\u5ba2\u7ba1\u7406\u300d\u30da\u30fc\u30b8\u3092\u958b\u3044\u305f\u72b6\u614b\u3067\u5b9f\u884c\u3057\u3066\u304f\u3060\u3055\u3044\u3002'); return; } var preview = records.slice(0, 5).map(function(r){ return '\u30fb' + r.name + (r.phone ? ' (' + r.phone + ')' : ''); }).join('\n'); if (records.length > 5) preview += '\n  \u307b\u304b ' + (records.length - 5) + '\u4ef6'; if (!confirm('\u3010CRM\u53d6\u8fbc\u3011' + records.length + '\u4ef6\u3092\u51e6\u7406\u3057\u307e\u3059\u3002\n\uff08\u65b0\u898f\u767b\u9332 + \u65e2\u5b58\u9867\u5ba2\u306e\u7a7a\u6b04\u88dc\u5b8c\uff09\n\n' + preview + '\n\nCRM\u306b\u9001\u4fe1\u3057\u307e\u3059\u304b\uff1f')) return; var payloadJson = JSON.stringify({ records: records }); var w = window.open('', '_blank', 'width=360,height=180,left=100,top=100'); if (!w) { alert('\u30dd\u30c3\u30d7\u30a2\u30c3\u30d7\u304c\u30d6\u30ed\u30c3\u30af\u3055\u308c\u3066\u3044\u307e\u3059\u3002\n\u30a2\u30c9\u30ec\u30b9\u30d0\u30fc\u53f3\u7aef\u306e\u30a2\u30a4\u30b3\u30f3\u3092\u30af\u30ea\u30c3\u30af\u3057\u3066\nlreach-crm-prototype.vercel.app\u306e\u30dd\u30c3\u30d7\u30a2\u30c3\u30d7\u3092\u8a31\u53ef\u3057\u3066\u304f\u3060\u3055\u3044\u3002'); return; } var escUrl   = JSON.stringify(ENDPOINT_URL); var escToken = JSON.stringify(INGEST_TOKEN); var escBody  = JSON.stringify(payloadJson); var cnt      = records.length; w.document.write( '<!DOCTYPE html><html><head><meta charset="utf-8">' + '<style>body{font-family:sans-serif;padding:20px;background:#f0f4ff;margin:0}' + 'p{font-size:15px;color:#333;margin:0 0 8px}' + '.sub{font-size:12px;color:#666}</style>' + '</head><body>' + '<p id="s">&#128228; CRM\u306b\u9001\u4fe1\u4e2d... (' + cnt + '\u4ef6)</p>' + '<p class="sub" id="d">\u3053\u306e\u30a6\u30a3\u30f3\u30c9\u30a6\u3092\u9589\u3058\u306a\u3044\u3067\u304f\u3060\u3055\u3044</p>' + '<script>' + 'var url=' + escUrl + ';' + 'var token=' + escToken + ';' + 'var body=' + escBody + ';' + 'fetch(url,{method:"POST",headers:{"Content-Type":"application/json","x-ingest-token":token},body:body})' + '.then(function(r){return r.json();})' + '.then(function(d){' + '  document.getElementById("s").textContent="\u2705 \u5b8c\u4e86\uff01 \u65b0\u898f:"+d.added+"\u4ef6 \u66f4\u65b0:"+d.updated+"\u4ef6 \u30b9\u30ad\u30c3\u30d7:"+d.skipped+"\u4ef6";' + '  document.getElementById("d").textContent="\u3053\u306e\u30a6\u30a3\u30f3\u30c9\u30a6\u3092\u9589\u3058\u3066\u304f\u3060\u3055\u3044";' + '  try{window.opener.postMessage("crm_ok_"+d.added+"_"+d.updated,"*");}catch(e){}' + '  setTimeout(function(){try{window.close();}catch(e){}},3000);' + '})' + '.catch(function(err){' + '  document.getElementById("s").textContent="\u274c \u30a8\u30e9\u30fc: "+err.message;' + '  document.getElementById("d").textContent="\u30a8\u30e9\u30fc\u304c\u767a\u751f\u3057\u307e\u3057\u305f";' + '});' + '<\/script></body></html>' ); w.document.close(); var done = false; function onMsg(ev) { if (typeof ev.data === 'string' && ev.data.indexOf('crm_ok_') === 0 && !done) { done = true; window.removeEventListener('message', onMsg); var parts = ev.data.replace('crm_ok_','').split('_'); var addedN = parts[0], updatedN = parts[1]; alert('\u3010CRM\u53d6\u8fbc \u5b8c\u4e86\u3011\n\u2705 \u65b0\u898f\u767b\u9332: ' + addedN + '\u4ef6\n\ud83d\udd04 \u60c5\u5831\u88dc\u5b8c\uff08\u66f4\u65b0\uff09: ' + updatedN + '\u4ef6\n\n\u304a\u3082\u308d\u3044CRM\u3092\u78ba\u8a8d\u3057\u3066\u304f\u3060\u3055\u3044\u3002'); } } window.addEventListener('message', onMsg); setTimeout(function(){ if (!done) { done = true; window.removeEventListener('message', onMsg); alert('\u3010CRM\u53d6\u8fbc\u3011\u9001\u4fe1\u3057\u307e\u3057\u305f\u3002\u304a\u3082\u308d\u3044CRM\u3092\u78ba\u8a8d\u3057\u3066\u304f\u3060\u3055\u3044\u3002'); } }, 10000); })();